{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://halcyon-threshold.pagewell.app/schema/incident.schema.json",
  "title": "Incident Evidence Kit record",
  "description": "Research prototype v0.1.0. Validation establishes structural and semantic consistency only, not legal compliance, factual truth, or safety.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "record_id",
    "status",
    "created_at",
    "reporter",
    "system",
    "event_window",
    "classification",
    "narrative",
    "impacts",
    "evidence",
    "actions",
    "uncertainties"
  ],
  "properties": {
    "schema_version": { "const": "0.1.0" },
    "record_id": {
